def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    mask = (1 << n) - 1
    value = int(state[::-1], 2)
    shifts = [d % n for d in offsets]

    while t:
        if t & 1:
            result = 0
            for shift in shifts:
                if shift:
                    result ^= (value >> shift) | ((value << (n - shift)) & mask)
                else:
                    result ^= value
            value = result
            if not value:
                return "0" * n

        shifts = [(shift * 2) % n for shift in shifts]
        t >>= 1

    return format(value, f"0{n}b")[::-1]
